  'splitsteps-p3' => 'Օգտագործելով աշխատասեղանի ծրագրակազմ. Բացեք PDF-ը: Ընտրեք էջեր՝ հանելու համար: Կարգավորեք բաժանման ընտրանքները: Սկսեք բաժանվել: Ընտրեք ելքի գտնվելու վայրը: Ներբեռնեք արդյունքները:',
  'splitsteps-p4' => 'Բարդ բաժանում. բաժանում ըստ էջանիշների: Շատ փաստաթղթեր ունեն էջանիշներ, որոնք նշում են հատվածի սահմանները: Ավտոմատ բաժանումն ըստ էջանիշների ավտոմատ կերպով բաժանում է փաստաթուղթը բաժինների սահմաններում:',
  'batchmerge-heading' => 'Խմբաքանակի միաձուլման աշխատանքային հոսքեր',
  'batchmerge-p1' => 'Միաձուլման կանոնավոր գործողությունների համար խմբաքանակային գործիքներն ավտոմատացնում են գործընթացը: Հավաքեք փաստաթղթերը նշված թղթապանակում: Կազմաձևեք միաձուլման կանոնները: Գործիքը ավտոմատ կերպով միաձուլում է փաստաթղթերը նշված հերթականությամբ:',
  'batchmerge-p2' => 'Ավտոմատացումը գործարկում է միաձուլումը, երբ փաստաթղթերը հասնում են: Երբ ֆայլերը ավելացվում են որոշակի թղթապանակում, գործընթացի միաձուլումը ավտոմատ կերպով գործարկվում է:',
  'batchmerge-p3' => 'Խմբաքանակի միաձուլումը խնայում է ժամեր այն թիմերի համար, որոնք կանոնավոր կերպով համատեղում են փաստաթղթերը: Այն, ինչ տևում է երեսուն րոպե, ձեռքով ավարտվում է վայրկյանների ընթացքում՝ ավտոմատացման միջոցով:',
  'batchsplit-heading' => 'Խմբաքանակի բաժանման աշխատանքային հոսքեր',
  'batchsplit-p1' => 'Խմբաքանակի բաժանումը ավտոմատացնում է բազմաթիվ փաստաթղթերից էջեր հանելը: Նշեք բաժանման չափանիշները: Գործիքը ավտոմատ կերպով բաժանում է բոլոր փաստաթղթերը:',
  'batchsplit-p2' => 'Խմբաքանակի բաժանման ընդհանուր սցենարները ներառում են յուրաքանչյուր փաստաթղթից առաջին էջի դուրս բերումը որպես շապիկ, վերջին էջը յուրաքանչյուր փաստաթղթից որպես ստորագրության էջ կամ էջերի արդյունահանում ըստ փաստաթղթի երկարության:',
  'batchsplit-p3' => 'Թիմերի համար, որոնք պարբերաբար բաժանում են փաստաթղթերը, խմբաքանակի աշխատանքային հոսքերը զգալիորեն խնայում են ժամանակ:',
  'quality-heading' => 'Փաստաթղթերի որակի պահպանում',
  'quality-p1' => 'Միաձուլված փաստաթղթերը պետք է հայտնվեն որպես միասնական միասնական փաստաթուղթ: Էջի համարակալումը պետք է շարունակվի միավորված փաստաթղթերում, այլ ոչ թե վերագործարկվի: Վերնագրերը և էջատակերը պետք է լինեն հետևողական:',
  'quality-p2' => 'Բաժանվելիս համոզվեք, որ արդյունահանված էջերը պահպանում են որակը: Անհրաժեշտության դեպքում սեղմել՝ բաժանված փաստաթղթերի ֆայլերի չափերը նվազեցնելու համար:',
  'quality-p3' => 'Ստուգեք միաձուլված և բաժանված փաստաթղթերը: Բացեք մի քանի ընթերցիչներ՝ ստուգելու համար, որ ձևաչափումը ճիշտ է տարբեր ծրագրերում:',
  'filesize-heading' => 'Ֆայլի չափի նկատառումներ',
  'filesize-p1' => 'Մի քանի խոշոր փաստաթղթերի միաձուլումը շատ մեծ ֆայլեր է ստեղծում: Որոշ էլփոստի համակարգեր չեն կարող կարգավորել չափազանց մեծ կցորդները:',
  'filesize-p2' => 'Եթե ​​միաձուլված ֆայլերը գերազանցում են չափի սահմանները, մտածեք բաժանվել ավելի փոքր միավորված խմբերի: Հիսուն փաստաթուղթ միավորելու փոխարեն, երկու անգամ միացրեք քսան փաստաթուղթ:',
  'filesize-p3' => '__COMPRESS_LINK__ փաստաթղթերը միաձուլվեցին՝ ֆայլի չափը նվազեցնելու համար: Սեղմումը նվազեցնում է չափը քառասունից վաթսուն տոկոսով՝ առանց որակի կորստի:',
  'organization-heading' => 'Կազմակերպում և անվանում',
  'organization-p1' => 'Միաձուլվելուց հետո վերանվանեք ֆայլերը նկարագրական կերպով: «Merged_Report_2026.pdf»-ն ավելի պարզ է, քան «merged.pdf»-ը:',
  'organization-p2' => 'Բաժանվելուց հետո արդյունահանված էջերը կազմակերպեք տրամաբանորեն։ Եթե ​​բաժանվում են ըստ գլուխների, անվանեք ֆայլերը, ներառյալ գլխի համարը և վերնագիրը:',
  'organization-p3' => 'Պահպանեք տարբերակի վերահսկողությունը: Եթե ​​փաստաթղթերը փոխվեն, միավորված տարբերակները պետք է թարմացվեն:',
  'organization-p4' => 'Ներառեք մետատվյալները միավորված փաստաթղթերում: Փաստաթղթերի միաձուլման ամսաթիվը, սկզբնական փաստաթղթերը և նպատակը:',
  'automation-heading' => 'Ավտոմատացման օրինակներ',
  'automation-p1' => 'Օրինակ 1. Շաբաթական հաշվետվության ժողով: Ամեն ուրբաթ միաձուլեք բաժնի հաշվետվությունները կազմակերպչական հաշվետվության մեջ: Ավտոմատ աշխատանքային հոսքի գործարկիչները միաձուլվում են: Զեկույցը ստեղծվել է ավտոմատ կերպով՝ առանց ձեռքի աշխատանքի:',
  'automation-p2' => 'Օրինակ 2. Պայմանագրի հավաքում: Պայմանագրի բաղադրիչները պահվում են առանձին փաստաթղթերում: Երբ պայմանագիրը ավարտվում է, բաղադրիչ փաստաթղթերը ավտոմատ կերպով միաձուլվում են ամբողջական պայմանագրի:',
  'automation-p3' => 'Օրինակ 3. Փաստաթղթերի բաշխում: Երկար փաստաթղթերը ավտոմատ կերպով բաժանվում են գլուխների: Բաժանորդները ստանում են միայն իրենց համապատասխան գլուխները՝ ելնելով նախասիրություններից:',
  'automation-p4' => 'Օրինակ 4. Պահուստային կազմակերպություն: Էլփոստի հավելվածները ավտոմատ կերպով միաձուլվում են կազմակերպված ֆայլերի մեջ: Նույն ուղարկողի կցորդները միավորվում են մեկ ֆայլի մեջ:',
  'mistakes-heading' => 'Ընդհանուր սխալներ',
  'mistakes-p1' => 'Անհասկանալի անուններով ֆայլեր ստեղծելը ժամանակ է վատնում միավորված փաստաթղթերը գտնելու համար: Միշտ օգտագործեք նկարագրական անուններ:',
  'mistakes-p2' => 'Փաստաթղթերի սխալ հերթականությամբ միավորելը անօգտագործելի արդյունքներ է ստեղծում: Միշտ ստուգեք պատվերը մինչև միաձուլումը վերջնական տեսքի բերելը:',
  'mistakes-p3' => 'Բնօրինակ փաստաթղթերը չպահպանելը նշանակում է կորցնել ճկունությունը: Պահպանեք բնօրինակ փաստաթղթերը, եթե միավորված տարբերակները թարմացման կարիք ունենան:',
  'mistakes-p4' => 'Առանց ներքևում գտնվող գործընթացները հաշվի առնելու բաժանումը խնդիրներ է ստեղծում: Ստուգեք, որ ներքևում գտնվող գործիքները կարող են կարգավորել պառակտված փաստաթղթերը:',
  'mistakes-p5' => 'Բարդ փաստաթղթերի աշխատանքային հոսքերը կառավարող թիմերի համար ինտեգրված գործողությունները լավագույնս աշխատում են: Փաստաթղթերի միաձուլումից հետո դրանք կարող են ձևաչափի փոխակերպման կամ սեղմման կարիք ունենալ բաշխման համար: Այս գործողությունների համատեղ պլանավորումը բարելավում է արդյունավետությունը:',
  'conclusion-heading' => 'Եզրակացություն',
  'conclusion-p1' => 'PDF-ի միաձուլումը և բաժանումը փաստաթղթերի կառավարման սովորական գործողություններ են: Համապատասխան գործիքներն ու աշխատանքային հոսքերը հեշտացնում են այս գործընթացները:',
  'conclusion-p2' => 'Երբեմն միաձուլման և բաժանման համար առցանց գործիքներն արագ լուծումներ են տալիս: Կանոնավոր գործառնությունների համար աշխատասեղանի ծրագրակազմը և ավտոմատացումը զգալիորեն խնայում են ժամանակ:',
  'conclusion-p3' => 'Ստուգեք միաձուլված և բաժանված փաստաթղթերը՝ որակն ապահովելու համար: Պահպանեք անվանման հստակ կոնվենցիաներ և կազմակերպություն:',
  'conclusion-p4' => 'Միավորել միաձուլումը և բաժանումը այլ PDF գործողությունների հետ: __COMPRESS_LINK__ փաստաթղթերը միավորեց՝ չափը նվազեցնելու համար: Անհրաժեշտության դեպքում __WORD_LINK__ փաստաթղթերը միաձուլվեցին խմբագրվող ձևաչափով:',
  'conclusion-p5' => 'Շատ փաստաթղթեր կառավարող կազմակերպությունները օգտվում են ավտոմատացման աշխատանքային հոսքերից: Ավտոմատ միաձուլումը և բաժանումը վերացնում է ձեռքով աշխատանքը և բարելավում հետևողականությունը:',
